      scaleFactor = readF64(source + 24),
      frameId = readU64(source + 32),
      slot = readU32(source + 40),
      texture =
        readAddress(source + w(44, 48)).let {
          if (scope != null) NativePointer.scoped(it, scope) else NativePointer.ofAddress(it)
        },
      device =
